/**
 * The logo as inline SVG, hidden from assistive technology: callers label it.
 * `id` prefixes the SVG's ids and must be unique on the page.
 */
export function logoSvg(options: { id: string; variant: LogoVariant; className: string }): string {
  const { id, variant, className } = options;
  return `<svg class="${className}" xmlns="http://www.w3.org/2000/svg" viewBox="${VIEW_BOX[variant]}" aria-hidden="true" focusable="false">${markup(variant, id)}</svg>`;
}
